import 'dart:convert';

import 'package:carrywise_app/services/id_document_check_service.dart';
import 'package:carrywise_app/services/ticket_check_service.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';

/// Runs on a simulator or phone (native OCR): a PDF ticket is turned into
/// images and read like a photo.
///   flutter test integration_test/pdf_reading_test.dart -d <device>
void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  // An e-ticket PDF for NIAMA/FORTUNE MR, Lagos -> London, 22 Nov 2026.
  final ticket = base64Decode(
    '',
  );

  testWidgets('a PDF ticket is read through its page images', (tester) async {
    final text = await IdDocumentCheckService.readDocumentText(
      ticket,
      'ticket.pdf',
    );
    // ignore: avoid_print
    print('OCR TEXT >>>\n$text<<<');
    expect(text, isNotNull);
    expect(TicketCheckService.nameOnTicket(text!, 'Fortune'), isTrue);
    expect(TicketCheckService.nameOnTicket(text, 'Niama'), isTrue);
  });

  testWidgets('the whole ticket check passes on it', (tester) async {
    final result =
        await TicketCheckService(
          loadProfile: () async => {
            'first_name': 'Fortune',
            'last_name': 'Niama',
          },
        ).check(
          bytes: ticket,
          fileName: 'ticket.pdf',
          departure: DateTime(2026, 11, 22),
          arrival: DateTime(2026, 11, 23),
        );
    expect(result, TicketCheckResult.passed);
  });

  testWidgets('someone else\'s name is not found on it', (tester) async {
    final result =
        await TicketCheckService(
          loadProfile: () async => {'first_name': 'Amara', 'last_name': 'Kalu'},
        ).check(
          bytes: ticket,
          fileName: 'ticket.pdf',
          departure: DateTime(2026, 11, 22),
          arrival: DateTime(2026, 11, 23),
        );
    expect(result, TicketCheckResult.nameMismatch);
  });
}
